package practice;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.ConcurrentModificationException;
import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Objects;

/** The ids of the tasks due on this tick of the scheduler, in the order they were scheduled. */
public class DueTasks implements Iterable<String> {

    private String[] ids = new String[4];
    private int size;

    /** Counts structural changes: every add and every removal. A set() is not one. */
    int modCount;

    public void add(String id) {
        if (size == ids.length) ids = Arrays.copyOf(ids, size * 2);
        ids[size++] = id;
        modCount++;
    }

    public String removeAt(int index) {
        Objects.checkIndex(index, size);
        String old = ids[index];
        System.arraycopy(ids, index + 1, ids, index, size - index - 1);
        ids[--size] = null;
        modCount++;
        return old;
    }

    public void set(int index, String id) {
        Objects.checkIndex(index, size);
        ids[index] = id;
    }

    public String get(int index) {
        Objects.checkIndex(index, size);
        return ids[index];
    }

    public int size() {
        return size;
    }

    public List<String> toList() {
        return new ArrayList<>(Arrays.asList(ids).subList(0, size));
    }

    @Override
    public Iterator<String> iterator() {
        return new Walk();
    }

    /** One walk over the list. */
    class Walk implements Iterator<String> {
        int cursor;                         // index of the next id to return
        int lastReturned = -1;              // index of the id next() returned last, -1 if none
        int expectedModCount = modCount;

        @Override
        public boolean hasNext() {
            return cursor < size;
        }

        /**
         * Returns the next id. If the list was changed structurally since this walk started, other
         * than through this walk's own remove(), it throws ConcurrentModificationException instead.
         * Past the end it throws NoSuchElementException.
         */
        @Override
        public String next() {
            if (modCount != expectedModCount) throw new ConcurrentModificationException();
            if (cursor >= size) throw new NoSuchElementException();
            lastReturned = cursor;
            return ids[cursor++];
        }

        /**
         * Removes the id the last next() returned. The walk carries on with the id that followed it,
         * and without throwing.
         */
        @Override
        public void remove() {
            if (lastReturned < 0) throw new IllegalStateException("next() first");
            if (modCount != expectedModCount) throw new ConcurrentModificationException();
            removeAt(lastReturned);
            cursor = lastReturned;
            lastReturned = -1;
            expectedModCount = modCount;
        }
    }
}

package practice;

import java.util.ConcurrentModificationException;
import java.util.Iterator;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            DueTasks tick = new DueTasks();
            for (String id : new String[] {"job-61", "job-62", "job-63", "job-64", "job-65"}) tick.add(id);
            StringBuilder visited = new StringBuilder();
            Iterator<String> walk = tick.iterator();
            while (walk.hasNext()) {
                String id = walk.next();
                visited.append(id).append(' ');
                if (id.equals("job-62") || id.equals("job-63")) walk.remove();
            }
            System.out.println("visited: " + visited.toString().trim());
            System.out.println("left after the walk: " + tick.toList());
            Iterator<String> careless = tick.iterator();
            careless.next();
            tick.add("job-66");
            try {
                System.out.println("next after an add behind the walk: " + careless.next());
            } catch (ConcurrentModificationException refused) {
                System.out.println("next after an add behind the walk: " + refused.getClass().getSimpleName());
            }
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

